CREATE TABLE IF NOT EXISTS "roles" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "name" text NOT NULL UNIQUE, "description" text, "active" boolean NOT NULL DEFAULT true, "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "permissions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "code" text NOT NULL UNIQUE, "module" text NOT NULL, "label" text NOT NULL);
CREATE TABLE IF NOT EXISTS "role_permissions" ("role_id" uuid NOT NULL REFERENCES "roles"("id"), "permission_id" uuid NOT NULL REFERENCES "permissions"("id"), "created_at" timestamp NOT NULL DEFAULT now(), PRIMARY KEY ("role_id", "permission_id"));
CREATE TABLE IF NOT EXISTS "user_preferences" ("user_id" text PRIMARY KEY REFERENCES "user"("id"), "theme" text NOT NULL DEFAULT 'system', "language" text NOT NULL DEFAULT 'pt-BR', "page_size" integer NOT NULL DEFAULT 25, "dense_tables" boolean NOT NULL DEFAULT false, "sidebar_collapsed" boolean NOT NULL DEFAULT false, "updated_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "notification_preferences" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "user_id" text NOT NULL REFERENCES "user"("id"), "event" text NOT NULL, "in_app" boolean NOT NULL DEFAULT true, "email" boolean NOT NULL DEFAULT false, "lead_time_minutes" integer DEFAULT 60, "updated_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "audit_logs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "user_id" text REFERENCES "user"("id"), "event" text NOT NULL, "module" text NOT NULL, "resource_id" text, "summary" text NOT NULL, "created_at" timestamp NOT NULL DEFAULT now());
